#include "cudaforge/kernels.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>

static void ok(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
template<class T> struct Device { T* p=nullptr;explicit Device(std::size_t n){ok(cudaMalloc(reinterpret_cast<void**>(&p),n*sizeof(T)));}~Device(){if(p)cudaFree(p);}Device(const Device&)=delete;Device& operator=(const Device&)=delete;};
int main(){try{int count=0;const auto device_status=cudaGetDeviceCount(&count);if(device_status==cudaErrorNoDevice||device_status==cudaErrorInsufficientDriver||count==0){std::cout<<"No usable CUDA device; skipped GPU correctness checks.\n";return 77;}ok(device_status);
 const std::size_t n=1031;std::vector<float>a(n),b(n),out(n),ref(n);for(std::size_t i=0;i<n;++i){a[i]=float(i%17)-8;b[i]=float(i%11)*.5f;}
 Device<float> da(n),db(n),dc(n);ok(cudaMemcpy(da.p,a.data(),n*sizeof(float),cudaMemcpyHostToDevice));ok(cudaMemcpy(db.p,b.data(),n*sizeof(float),cudaMemcpyHostToDevice));
 cudaforge::cpu::vector_add(a.data(),b.data(),ref.data(),n);cudaforge::cuda::vector_add_naive(da.p,db.p,dc.p,n);ok(cudaMemcpy(out.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));for(std::size_t i=0;i<n;++i)if(std::abs(out[i]-ref[i])>1e-5f)throw std::runtime_error("vector add mismatch");
 cudaforge::cuda::vector_add_optimized(da.p,db.p,dc.p,n);ok(cudaMemcpy(out.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));for(std::size_t i=0;i<n;++i)if(std::abs(out[i]-ref[i])>1e-5f)throw std::runtime_error("optimized vector add mismatch");
 const double sum=cudaforge::cpu::reduce_sum(a.data(),n);if(std::abs(cudaforge::cuda::reduce_sum_naive(da.p,n)-sum)>1e-4||std::abs(cudaforge::cuda::reduce_sum_optimized(da.p,n)-sum)>1e-4)throw std::runtime_error("sum mismatch");Device<double> dsum(1),dss(n);cudaforge::cuda::reduce_sum_device(da.p,dsum.p,dss.p,n);double gpu_sum=0;ok(cudaMemcpy(&gpu_sum,dsum.p,sizeof(double),cudaMemcpyDeviceToHost));if(std::abs(gpu_sum-sum)>1e-4)throw std::runtime_error("launch-only sum mismatch");
 const float maximum=cudaforge::cpu::reduce_max(a.data(),n);if(cudaforge::cuda::reduce_max_naive(da.p,n)!=maximum||cudaforge::cuda::reduce_max_optimized(da.p,n)!=maximum)throw std::runtime_error("maximum mismatch");Device<float> dmax(1),dms(n);cudaforge::cuda::reduce_max_device(da.p,dmax.p,dms.p,n);float gpu_max=0;ok(cudaMemcpy(&gpu_max,dmax.p,sizeof(float),cudaMemcpyDeviceToHost));if(gpu_max!=maximum)throw std::runtime_error("launch-only maximum mismatch");
 cudaforge::cpu::inclusive_scan(a.data(),ref.data(),n);cudaforge::cuda::inclusive_scan_naive(da.p,dc.p,n);ok(cudaMemcpy(out.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));for(std::size_t i=0;i<n;++i)if(std::abs(out[i]-ref[i])>1e-4f)throw std::runtime_error("naive scan mismatch");cudaforge::cuda::inclusive_scan_optimized(da.p,dc.p,n);ok(cudaMemcpy(out.data(),dc.p,n*sizeof(float),cudaMemcpyDeviceToHost));for(std::size_t i=0;i<n;++i)if(std::abs(out[i]-ref[i])>1e-4f)throw std::runtime_error("tiled scan mismatch");
 constexpr std::size_t m=19,k=13,q=23;std::vector<float>x(m*k,1),y(k*q,2),z(m*q),zr(m*q);Device<float> dx(x.size()),dy(y.size()),dz(z.size());ok(cudaMemcpy(dx.p,x.data(),x.size()*sizeof(float),cudaMemcpyHostToDevice));ok(cudaMemcpy(dy.p,y.data(),y.size()*sizeof(float),cudaMemcpyHostToDevice));cudaforge::cpu::matmul(x.data(),y.data(),zr.data(),m,q,k);cudaforge::cuda::matmul_naive(dx.p,dy.p,dz.p,m,q,k);ok(cudaMemcpy(z.data(),dz.p,z.size()*sizeof(float),cudaMemcpyDeviceToHost));if(z!=zr)throw std::runtime_error("naive matmul mismatch");cudaforge::cuda::matmul_optimized(dx.p,dy.p,dz.p,m,q,k);ok(cudaMemcpy(z.data(),dz.p,z.size()*sizeof(float),cudaMemcpyDeviceToHost));if(z!=zr)throw std::runtime_error("tiled matmul mismatch");
 std::cout<<"CUDA correctness checks passed on " ;cudaDeviceProp prop{};ok(cudaGetDeviceProperties(&prop,0));std::cout<<prop.name<<".\n";
 }catch(const std::exception&e){std::cerr<<"CUDA test failure: "<<e.what()<<'\n';return 1;}return 0;}
